def solve_n_queens(n):
    def is_safe(board, row, col):
        for i in range(row):
            # Check column
            if board[i] == col:
                return False
            # Check diagonals
            if abs(board[i] - col) == abs(i - row):
                return False
        return True

    def solve(board, row):
        if row == n:
            return board[:]
        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                result = solve(board, row + 1)
                if result is not None:
                    return result
                board[row] = -1
        return None

    board = [-1] * n
    return solve(board, 0)

solution = solve_n_queens(7)
print(f"Solution: {solution}")

# Verify the solution
if solution:
    print("Verifying solution...")
    valid = True
    for i in range(7):
        for j in range(i+1, 7):
            if solution[i] == solution[j]:
                print(f"Queens at rows {i} and {j} share column {solution[i]}")
                valid = False
            if abs(solution[i] - solution[j]) == abs(i - j):
                print(f"Queens at rows {i} and {j} are on same diagonal")
                valid = False
    if valid:
        print("Solution is valid!")
    else:
        print("Solution is invalid!")
